-- Every ISO 3166-1 country in the geography vocabulary (live recheck
-- 2026-10-30).
--
-- An investor said "Benelux and the Nordics" and nothing could be recorded:
-- the vocabulary held 47 entries, built region by region, with no Belgium,
-- no Luxembourg and no Nordic country. This adds the other 215 ISO 3166-1
-- countries and territories (each with its alpha-2 code in metadata, so
-- declared geography fit can match a company's headquarters), plus the
-- regions investors name whose members are all new: the Nordics, Central &
-- Eastern Europe ("CEE"), Southern Europe, East Asia, Central Asia, Central
-- America, the Caribbean, and Oceania. Antarctica (AQ) is a root with the
-- territories around it. A region that would contain a country already
-- listed (Benelux, Western Europe, Southeast Asia) is not added: that would
-- re-parent existing rows. "Benelux" is read as its three countries by the
-- category reader instead.
--
-- An ISO code that is also an everyday word or investment shorthand ("NO",
-- "IT", "ME", "VC", "PE", "AI", "ML") is not an alias; the country is found
-- by its name.
--
-- Rendered from @capital-q/taxonomy reference-data (geography v5): stable
-- v5 ids. Additive only: no existing node, alias, grant or policy changes,
-- nothing is dropped, and re-running does nothing. The vocabulary version
-- moves to 5 (ADR 0005) so snapshots and slates can tell the vocabulary grew.

on conflict (id) do nothing;

on conflict (id) do nothing;

update taxonomy.vocabularies
   set version = 5
 where id = '512652ee-b4a7-519f-ae12-9db2b1607ee2'
   and version < 5;

-- Companies headquartered in a newly listed country now have a geography
-- node; their knowledge projection is refreshed so its ancestors are there.
do $$
declare
  target uuid;
begin
  for target in
    select c.id from core.companies c
     where c.headquarters_country in (
       'AQ', 'IE', 'BE', 'LU', 'AT', 'CH', 'LI', 'MC', 'IM', 'JE', 'GG', 'BM',
       'PM', 'MX', 'AR', 'BO', 'CL', 'CO', 'EC', 'FK', 'GF', 'GY', 'PY', 'PE',
       'SR', 'UY', 'VE', 'IL', 'PS', 'JO', 'LB', 'SY', 'IQ', 'IR', 'YE', 'TR',
       'PK', 'BD', 'LK', 'NP', 'BT', 'MV', 'AF', 'ID', 'MY', 'TH', 'VN', 'PH',
       'MM', 'KH', 'LA', 'BN', 'TL', 'GE', 'AM', 'AZ', 'AU', 'NZ', 'FJ', 'PG',
       'WS', 'TO', 'VU', 'SB', 'KI', 'TV', 'NR', 'MH', 'FM', 'PW', 'NC', 'PF',
       'GU', 'AS', 'MP', 'CK', 'NU', 'TK', 'WF', 'PN', 'NF', 'CX', 'CC', 'UM',
       'BV', 'HM', 'TF', 'GS', 'BF', 'CV', 'GM', 'GN', 'GW', 'LR', 'ML', 'MR',
       'NE', 'SL', 'SH', 'BI', 'KM', 'DJ', 'ER', 'MG', 'MU', 'SC', 'SO', 'SS',
       'RE', 'YT', 'IO', 'AO', 'CF', 'TD', 'CG', 'GA', 'GQ', 'ST', 'NA', 'ZW',
       'MZ', 'MW', 'LS', 'SZ', 'DZ', 'LY', 'SD', 'EH', 'DK', 'SE', 'NO', 'FI',
       'IS', 'FO', 'AX', 'GL', 'SJ', 'PL', 'CZ', 'SK', 'HU', 'RO', 'BG', 'SI',
       'HR', 'EE', 'LV', 'LT', 'RS', 'BA', 'ME', 'MK', 'AL', 'MD', 'UA', 'BY',
       'RU', 'ES', 'PT', 'IT', 'GR', 'MT', 'CY', 'AD', 'SM', 'VA', 'GI', 'BZ',
       'CR', 'SV', 'GT', 'HN', 'NI', 'PA', 'AI', 'AG', 'AW', 'BS', 'BB', 'BQ',
       'VG', 'KY', 'CU', 'CW', 'DM', 'DO', 'GD', 'GP', 'HT', 'JM', 'MQ', 'MS',
       'PR', 'BL', 'KN', 'LC', 'MF', 'VC', 'SX', 'TT', 'TC', 'VI', 'CN', 'HK',
       'MO', 'JP', 'KR', 'KP', 'MN', 'TW', 'KZ', 'KG', 'TJ', 'TM', 'UZ'
     )
  loop
    perform knowledge.refresh_company_profile(target);
  end loop;
end;
$$;
